// Project [lon, lat] into the shared world equirectangular coord space
// (matches WORLD_MAP_VIEWBOX_WIDTH/HEIGHT from world-map-paths.ts).
export function projectGeoCoord(lon: number, lat: number): [number, number] {
  return [(lon + 180) * CHINA_MAP_LON_SCALE, (90 - lat) * CHINA_MAP_LAT_SCALE];
}
